    public const string Html="""
<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Otter Community Events</title>
<style>
:root{color-scheme:dark;--gold:#f6cc71;--aqua:#7be9ed}*{box-sizing:border-box}html,body{margin:0;background:transparent;color:#f3f7fc;font:16px 'Segoe UI',sans-serif;overflow:hidden}
main{width:min(100vw,900px);padding:12px}.hidden{display:none!important}.panel{display:grid;grid-template-columns:56% 44%;position:relative;border:1px solid #64b9d15c;border-radius:20px;background:linear-gradient(145deg,#081525f7,#0a2432f5);overflow:hidden;box-shadow:0 8px 24px #0005}
.art{position:relative;min-width:0;align-self:center;background:#071321;overflow:hidden}.art svg{display:block;width:100%;height:auto;overflow:hidden}.art-Heist{aspect-ratio:1010/504}.art-Heist svg{height:100%}.art-Rennen{aspect-ratio:762/509}.art-Bosskampf{aspect-ratio:763/509}.art-Rennen svg,.art-Bosskampf svg{height:100%}
.content{padding:24px;min-width:0;display:flex;flex-direction:column;justify-content:center;border-left:1px solid #76bdd123;gap:12px}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2px;color:var(--aqua)}h1,h2,p{margin:0}h1,h2{font-size:22px;line-height:1.2;font-weight:700;color:#fff;overflow-wrap:anywhere}.badge{align-self:flex-start;font-size:11px;font-weight:700;letter-spacing:.4px;color:var(--gold);border:1px solid #f6cc7148;border-radius:20px;padding:5px 10px}
.headline{font-size:19px;line-height:1.3;font-weight:700;color:var(--gold);overflow-wrap:anywhere}.detail{font-size:13px;color:#bfd1df;line-height:1.5;overflow-wrap:anywhere}.metrics{display:flex;flex-wrap:wrap;gap:6px}.metric{font-size:12px;padding:6px 9px;background:#04121db3;border:1px solid #8cc7da26;border-radius:8px;overflow-wrap:anywhere}.metric strong{color:var(--aqua)}.names{display:flex;flex-wrap:wrap;gap:5px;max-height:58px;overflow:auto;scrollbar-width:thin;scrollbar-color:#406776 transparent}.name{font-size:11px;border:1px solid #6993aa40;background:#24455765;border-radius:12px;padding:4px 7px;overflow-wrap:anywhere;max-width:100%}
progress{width:100%;height:17px;accent-color:#ff677a;border:0;border-radius:20px;overflow:hidden;background:#03111d}progress::-webkit-progress-bar{background:#03111d}progress::-webkit-progress-value{background:linear-gradient(90deg,#e64464,#ff8d78);border-radius:20px}.progress{height:6px;background:#03111d;border-radius:20px;overflow:hidden}.progress>i{display:block;height:100%;background:linear-gradient(90deg,#61ced5,var(--gold));transition:width .3s}
.command{font-size:13px;color:#fff;background:#0b3443;border:1px solid #70d9e53d;border-radius:9px;padding:9px 12px}.command strong{color:var(--aqua)}.hot{margin-top:9px;padding:10px 15px;border:1px solid #f3b95788;border-radius:12px;background:#1f230ff2;font-size:13px;line-height:1.4}.urgent{animation:urgent 1s ease-in-out infinite alternate}
.art::after{content:"";position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 24px #0003}.raiding .art::after{background:linear-gradient(110deg,transparent 35%,#8bdded19 49%,transparent 63%);background-size:300% 100%;animation:scan 3s linear infinite}.success{border-color:#f4cf75b3}.failed .art svg{filter:saturate(.55)}.pearls{position:absolute;left:35%;top:55%;pointer-events:none}.pearl{position:absolute;width:8px;height:8px;border-radius:50%;background:radial-gradient(circle at 30% 20%,#fff,#9ce8f2 60%,#c7a8df);opacity:0}.success.effects .pearl{animation:pearl 2s ease-out infinite;animation-delay:calc(var(--i)*.09s)}
.enter{animation:fadeIn .5s ease}.hiding{animation:fadeOut 1s ease forwards}.preview{position:relative;z-index:10;margin:8px;padding:10px 12px;max-width:880px;border:1px dashed #d8b772;border-radius:10px;background:#0b2030;font-size:11px}.preview button{margin:4px 4px 0 0;padding:6px 9px;color:white;background:#173f50;border:1px solid #51889d;border-radius:6px;cursor:pointer}.testflag{color:var(--gold);font-weight:700}.blankhint{display:block;margin-top:7px;color:#bed2df;font-size:11px}
@keyframes fadeIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}@keyframes fadeOut{to{opacity:0;transform:translateY(8px)}}@keyframes urgent{to{border-color:#ff7b45;color:#ffd396}}@keyframes pearl{0%{opacity:0;transform:none}25%{opacity:1}100%{opacity:0;transform:translate(calc(var(--dx)*1px),-140px)}}@keyframes scan{to{background-position:-300% 0}}
@media(max-width:750px){main{width:min(100vw,calc((100vh - 225px)*1.5));padding:8px}.panel{display:flex;flex-direction:column;border-radius:16px}.art{width:100%;flex:none}.content{border-left:0;border-top:1px solid #76bdd123;padding:13px 16px;gap:7px}.eyebrow{font-size:9px}h1,h2{font-size:18px}.headline{font-size:16px}.detail,.command{font-size:12px;line-height:1.3}.metrics{gap:5px}.metric{padding:4px 7px;font-size:11px}.names{max-height:24px;margin:0}.name{font-size:10px;padding:3px 6px}.badge{font-size:10px;padding:3px 8px}.command{padding:6px 9px}.is-preview{overflow:auto}.is-preview main{width:min(100vw,600px)}.hot{font-size:11px;padding:7px 11px}}

/* Mimic: supplied artwork, with its own warm palette and real boss values. */
.panel.mimic{grid-template-columns:46% 54%;border-color:#e9ad4f99;background:linear-gradient(135deg,#23130ef7,#111b26f7);box-shadow:0 8px 25px #0007,inset 0 0 24px #d68f2020}.mimic .art{aspect-ratio:1;background:#20140f}.art img{display:block;width:100%;height:100%;object-fit:cover}.mimic .content{border-left-color:#e8b35a44;gap:13px}.mimic .eyebrow{color:#ffbb65}.mimic h2{font:700 29px Georgia,serif;color:#ffe1a0;text-shadow:0 2px 6px #000}.mimic .badge{color:#ffca7c;border-color:#ed9b4e66;background:#6a2d182c}.mimic .command{background:#3a241b;border-color:#df9a4d66}.mimic .command strong{color:#ffd080}.mimic progress::-webkit-progress-value{background:linear-gradient(90deg,#ad3f24,#f9ad44)}.mimic #bossTime{color:#ffcf87}.mimic #hp{color:#ffdfb0}.mimic .detail{font-size:12px}
@media(max-width:750px){.mimic .art{aspect-ratio:1.7}.mimic .art img{object-position:center 42%}.mimic .content{gap:7px;border-left:0;border-top-color:#e8b35a44}.mimic h2{font-size:21px}.mimic .detail{font-size:11px}}
@media(prefers-reduced-motion:reduce){*,*::after{animation:none!important;transition:none!important}}
</style>
<div id="preview" class="preview hidden"><span class="testflag">LOKALE VORSCHAU – Mockdaten, keine Perlen oder Chatmeldungen</span><div id="buttons"></div><span class="blankhint">Deine Originalmotive · Getrennte Bildausschnitte ohne weiße Ränder · OBS: 900 × 600 oder 600 × 500</span></div>
<main>
<section id="heist" class="panel hidden" aria-live="polite">
<div class="art art-Heist"><svg viewBox="263 519 1010 504" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Otter-Abenteuer: Heist"><image href="/assets/otter-events.png" width="1536" height="1024"/></svg></div><div id="pearls" class="pearls"></div>
<div class="content"><div class="eyebrow">COMMUNITY HEIST</div><h1 id="title"></h1><span class="badge" id="phase"></span><p id="headline" class="headline"></p><p id="detail" class="detail"></p><div class="metrics"><span class="metric">Crew: <strong id="count"></strong></span><span class="metric" id="jackpot"></span><span class="metric" id="entry"></span></div><div class="progress"><i id="timebar"></i></div><div id="names" class="names"></div></div></section>
<section id="boss" class="panel hidden" aria-live="polite">
<div class="art art-Bosskampf"><img id="mimicArt" class="hidden" src="/assets/mimic.png" alt="Mimic – lebendige Schatztruhe" width="1254" height="1254"><svg id="normalBossArt" viewBox="773 0 763 509" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Otter-Abenteuer: Bosskampf"><image href="/assets/otter-events.png" width="1536" height="1024"/></svg></div>
<div class="content"><div id="bossEyebrow" class="eyebrow">COMMUNITY BOSS</div><h2 id="bossTitle">Gemeinsam gegen die Tiefe</h2><span id="mimicBadge" class="badge hidden">DIE SCHATZTRUHE LEBT!</span><progress id="health" aria-label="Boss-Lebenspunkte"></progress><p id="hp" class="headline"></p><div class="metrics"><span id="bossTime" class="metric"></span><span id="fighters" class="metric"></span></div><p id="mimicLoot" class="detail hidden"></p><div class="command">Gemeinsam besiegen: <strong>!attack</strong></div></div></section>
<section id="race" class="panel hidden" aria-live="polite">
<div class="art art-Rennen"><svg viewBox="0 0 762 509" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Otter-Abenteuer: Rennen"><image href="/assets/otter-events.png" width="1536" height="1024"/></svg></div>
<div class="content"><div class="eyebrow">COMMUNITY RENNEN</div><h2>Auf die Pfoten, fertig, los!</h2><p id="raceTime" class="headline"></p><div class="metrics"><span id="racers" class="metric"></span><span id="stake" class="metric"></span></div><div class="command">Mitmachen: <strong>!joinrace</strong></div></div></section>
<aside id="hot" class="hot hidden"></aside></main>
<script>
const el=id=>document.getElementById(id),preview=location.pathname==='/preview',mimicOnly=location.pathname==='/mimic';let state=null,adventure={},offset=0,lastId='',lastPhase='',knownNames=new Set(),mock=null,mockBlock='',joinStart=0;const nf=new Intl.NumberFormat('de-DE');
const now=()=>Date.now()+offset,seconds=end=>Math.max(0,Math.ceil((Date.parse(end)-now())/1000));
for(let i=0;i<18;i++){let p=document.createElement('i');p.className='pearl';p.style.setProperty('--i',i);p.style.setProperty('--dx',(i-8)*18);el('pearls').append(p)}
function hideAll(){for(const id of ['heist','boss','race','hot'])el(id).classList.add('hidden')}
function render(){hideAll();if(!state)return;const kind=state.Current?.Type;const h=state.Heist;
if(mimicOnly&&(!adventure.BossActive||!adventure.BossIsMimic||!Number.isFinite(Date.parse(adventure.BossEndsAt))||seconds(adventure.BossEndsAt)<=0))return;
if(mimicOnly||kind===0){const mimic=adventure.BossIsMimic===true;if(mimic&&seconds(adventure.BossEndsAt)<=0)return;
const panel=el('boss');panel.classList.remove('hidden');panel.classList.toggle('mimic',mimic);panel.classList.toggle('urgent',mimic&&seconds(adventure.BossEndsAt)<=15);
el('mimicArt').classList.toggle('hidden',!mimic);el('normalBossArt').classList.toggle('hidden',mimic);el('mimicBadge').classList.toggle('hidden',!mimic);
el('bossEyebrow').textContent=mimic?'SELTENER COMMUNITY BOSS':'COMMUNITY BOSS';el('bossTitle').textContent=mimic?(adventure.BossName||'Mimic – Lebende Schatztruhe'):'Gemeinsam gegen die Tiefe';
el('health').max=adventure.BossMaxHp||1;el('health').value=adventure.BossHp||0;el('hp').textContent=`${nf.format(adventure.BossHp||0)} / ${nf.format(adventure.BossMaxHp||0)} LP`;
const left=seconds(adventure.BossEndsAt);el('bossTime').textContent=Number.isFinite(left)?`Verbleibend: ${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`:'Zeit nicht verfügbar';el('fighters').textContent=`${adventure.BossPlayers||0} Kämpfer`;
const loot=adventure.BossLegendaryChance;el('mimicLoot').classList.toggle('hidden',!mimic||!Number.isFinite(loot));el('mimicLoot').textContent=Number.isFinite(loot)?`Legendary-Chance: ${nf.format(loot)} % je berechtigtem Überlebenden nach einem Sieg.`:'';}
else if(kind===1){el('race').classList.remove('hidden');el('racers').textContent=`${adventure.RacePlayers||0} Teilnehmer`;el('raceTime').textContent=`Start in ${seconds(adventure.RaceEndsAt)}s`;el('stake').textContent=`Einsatz: ${nf.format(adventure.RaceStake||0)}`}
else if(kind===2&&h){let phase=h.Phase;
if(h.PresentationStartedAt){const elapsed=(now()-Date.parse(h.PresentationStartedAt))/1000;phase=elapsed<h.AnimationSeconds&&phase!=='Cancelled'?'Raiding':elapsed>=h.AnimationSeconds+h.ResultSeconds?'Hiding':h.Phase==='Raiding'?'Evaluating':h.Phase}
if(h.EventId!==lastId){lastId=h.EventId;lastPhase='';knownNames.clear();joinStart=Date.parse(h.StartedAt)}
const changed=phase!==lastPhase;lastPhase=phase;const p=el('heist');p.className='panel '+(phase==='Raiding'?'raiding':phase==='Successful'?'success'+(h.SuccessAnimation?' effects':''):phase==='Failed'&&h.FailureAnimation?'failed':phase==='Hiding'?'hiding':'')+(changed?' enter':'');p.style.setProperty('--speed',h.AnimationSeconds+'s');
el('title').textContent=h.Name;el('phase').textContent=phase==='Joining'?'Crew sammeln':phase==='Raiding'?'Überfall läuft':phase==='Successful'?'Schatz geborgen':phase==='Cancelled'?'Abgebrochen':phase==='Hiding'?'Bis zum nächsten Abenteuer':phase==='Failed'?'Fehlgeschlagen':'Auswertung';
const remaining=seconds(h.JoinEndsAt);el('headline').textContent=phase==='Joining'?`Beitritt noch ${remaining} Sekunden möglich!`:phase==='Raiding'?'Die Otter-Crew knackt die Schatzkammer …':phase==='Successful'?`💰 ${nf.format(h.TotalPayout)} ${h.Currency} erbeutet!`:phase==='Failed'?'Die Schatzkammer bleibt verschlossen.':phase==='Cancelled'?'Zu wenige Pfoten oder Heist abgebrochen.':phase==='Hiding'?'Die Crew schwimmt nach Hause.':'Die Beute wird ausgewertet …';
el('detail').textContent=phase==='Joining'?`Mitmachen: ${h.JoinCommand} · Der bestehende Heist verteilt den Jackpot.`:phase==='Successful'?`${h.ParticipantCount} Teilnehmer teilen die tatsächliche Auszahlung.`:phase==='Failed'?`Keine Auszahlung. Verlorene ${h.Currency}: ${nf.format(h.TotalLost)}. Der Jackpot bleibt erhalten.`:phase==='Cancelled'?'Keine Auszahlung, keine Einsätze verloren.':'Das Ergebnis stammt ausschließlich aus der Spiellogik.';
el('count').textContent=h.ParticipantCount;el('jackpot').textContent=`Jackpot: ${nf.format(h.Jackpot)} ${h.Currency}`;el('entry').textContent=h.EntryStake?`Einsatz: ${nf.format(h.EntryStake)}`:'Teilnahme ohne Einsatz';
el('timebar').style.width=phase==='Joining'?Math.max(0,Math.min(100,(Date.parse(h.JoinEndsAt)-now())/Math.max(1,Date.parse(h.JoinEndsAt)-joinStart)*100))+'%':'100%';
const players=h.Players||[];const names=players.map(x=>x.Name).join('\u0001')+phase;if(el('names').dataset.key!==names){el('names').dataset.key=names;el('names').replaceChildren();for(const person of players){const n=document.createElement('span');n.className='name';n.textContent=person.Name+(phase==='Successful'?` +${nf.format(person.Payout)}`:'');el('names').append(n)}}
}
if(!mimicOnly&&state.HotTimeActive){const left=seconds(state.HotTimeEndsAt);if(left>0){el('hot').classList.remove('hidden');el('hot').classList.toggle('urgent',left<=30);el('hot').textContent=`🔥 HOT TIME · +${state.HotTimeDrop}% relative Dropchance · +${state.HotTimePearls}% Perlen · ${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`}}
}
async function poll(){if(preview)return;try{const [r,a]=await Promise.all([fetch('/community',{cache:'no-store'}),fetch('/state',{cache:'no-store'})]);if(!r.ok||!a.ok)throw Error();state=await r.json();adventure=await a.json();if(!state)state={Current:adventure.BossActive?{Type:0}:adventure.RaceActive?{Type:1}:null,ServerNow:new Date().toISOString()};offset=Date.parse(state.ServerNow)-Date.now();render()}catch{state=null;hideAll()}setTimeout(poll,500)}
function previewRender(){const t=new Date();state={ServerNow:t.toISOString(),Current:mock?{Type:2}:null,Heist:mock,HotTimeActive:false};adventure={};if(mock?.PresentationStartedAt){const elapsed=(Date.now()-Date.parse(mock.PresentationStartedAt))/1000;if(elapsed>=mock.AnimationSeconds+mock.ResultSeconds+1){mock=null;state.Current=null;state.Heist=null}else if(elapsed>=mock.AnimationSeconds)mock.Phase=mock.Phase==='Raiding'?mock.Result:mock.Phase}
if(mockBlock==='Boss'){state.Current={Type:0};state.Heist=null;adventure={BossHp:720,BossMaxHp:1000,BossPlayers:8,BossEndsAt:new Date(Date.now()+45000).toISOString()}}if(mockBlock==='Mimic'){state.Current={Type:0};state.Heist=null;adventure={BossActive:true,BossIsMimic:true,BossName:'Mimic – Lebende Schatztruhe',BossHp:720,BossMaxHp:1000,BossPlayers:8,BossLegendaryChance:50,BossEndsAt:new Date(Date.now()+45000).toISOString()}}if(mockBlock==='Rennen'){state.Current={Type:1};state.Heist=null;adventure={RacePlayers:6,RaceStake:100,RaceEndsAt:new Date(Date.now()+25000).toISOString()}}render()}
if(preview){document.body.classList.add('is-preview');el('preview').classList.remove('hidden');const actions={
'Heist starten':()=>{mock={EventId:'preview-'+Date.now(),Name:'Überfall auf die Perlenschatzkammer',Phase:'Joining',StartedAt:new Date().toISOString(),JoinEndsAt:new Date(Date.now()+60000).toISOString(),JoinCommand:'!joinheist',Currency:'Perlen',Jackpot:4800,EntryStake:0,ParticipantCount:1,Players:[{Name:'TestOtter',Payout:0,Lost:0}],TotalPayout:0,TotalLost:0,AnimationSeconds:6,ResultSeconds:10,SuccessAnimation:true,FailureAnimation:true};mockBlock=''},
'Teilnehmer hinzufügen':()=>{if(mock?.Phase==='Joining'){mock.ParticipantCount++;mock.Players.push({Name:'Otter '+mock.ParticipantCount,Payout:0,Lost:0})}},
'Zeit vorspulen':()=>{if(mock)mock.JoinEndsAt=new Date(Date.now()+3000).toISOString()},
'Erfolg':()=>finish(true),'Niederlage':()=>finish(false),'Boss anzeigen':()=>{mockBlock='Boss'},'Mimic anzeigen':()=>{mockBlock='Mimic'},'Rennen anzeigen':()=>{mockBlock='Rennen'},'Konflikt beenden':()=>{mockBlock=''},'Ausblenden':()=>{mock=null;mockBlock=''}};
function finish(success){if(!mock)return;mock.JoinEndsAt=new Date().toISOString();mock.Phase='Raiding';mock.Result=success?'Successful':'Failed';mock.PresentationStartedAt=new Date().toISOString();mock.TotalPayout=success?4800:0;mock.Players.forEach((p,i)=>p.Payout=success?Math.floor(4800/mock.ParticipantCount)+(i<4800%mock.ParticipantCount?1:0):0)}
for(const [label,fn]of Object.entries(actions)){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{fn();previewRender()};el('buttons').append(b)}actions['Heist starten']();setInterval(previewRender,200)}else{setInterval(render,250);poll()}
</script></html>
""";
}

